def verify_assumption_G(tau_i, windows, p_i):
    for j in range(len(windows)):
        s_j, t_j = windows[j]
        assert t_j - s_j <= p_i, "Window too long"
        if j > 0:
            assert s_j - windows[j-1][0] >= p_i, "Windows too close"
        assert no_releases_in_gap(t_j_minus_1, s_j)
        assert all_deadlines_before(s_j, t_j, t_j)

def compute_W_recursively(W_prev, X_j, Y_j, b_i):
    W_j = W_prev + X_j - Y_j * b_i
    return max(0, W_j)

def compute_all_W(X_sequence, Y_sequence, b_i):
    W = [0]  # W_0 = 0
    for j in range(1, len(X_sequence)):
        W_j = compute_W_recursively(W[j-1], X_sequence[j], 
                                     Y_sequence[j], b_i)
        W.append(W_j)
    return W

def check_probabilistic_deadline(tau_i, b_i, B_i_T_A, delta_i, eta_i):
    quantile_bound = quantile_response_time_bound(tau_i, b_i, B_i_T_A, 
                                                    1 - eta_i)
    if quantile_bound <= delta_i:
        return True  # Probabilistic deadline satisfied
    return False
